CREATE OR REPLACE FUNCTION app.visual_definition_nodes(p_doc jsonb)
 RETURNS SETOF jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  WITH RECURSIVE walk(node) AS (
    SELECT value FROM jsonb_array_elements(COALESCE(p_doc->'nodes','[]'::jsonb))
    UNION ALL SELECT value FROM walk CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN node->>'type'='element' THEN COALESCE(node->'children','[]'::jsonb)
        WHEN node->>'type'='repeat' THEN node->'item' ELSE '[]'::jsonb END)
  ) SELECT node FROM walk
$function$
